import React, { useRef, useEffect } from 'react';
import { Animated, View, Text, StyleSheet, Pressable } from 'react-native';

const AwesomeButton = ({
  children,
  raiseLevel = 4,
  backgroundColor = '#C0C0C0',
  backgroundDarker = '#9F9F9F',
  backgroundShadow = '#C0C0C0',
  borderRadius = 4,
  onPress,
  onPressIn,
  onPressedIn,
  onPressOut,
  onPressedOut,
  disabled = false,
  ...props
}) => {
  const translateY = useRef(new Animated.Value(0)).current;
  const shadowOpacity = useRef(new Animated.Value(0.8)).current;

  const handlePressIn = () => {
    onPressIn?.();
    Animated.parallel([
      Animated.spring(translateY, {
        toValue: raiseLevel,
        tension: 180,
        friction: 12,
        useNativeDriver: true,
      }),
      Animated.timing(shadowOpacity, { toValue: 0.2, duration: 80, useNativeDriver: true })
    ]).start(() => onPressedIn?.());
  };

  const handlePressOut = () => {
    onPressOut?.();
    Animated.parallel([
      Animated.spring(translateY, {
        toValue: 0,
        tension: 180,
        friction: 12,
        useNativeDriver: true,
      }),
      Animated.timing(shadowOpacity, { toValue: 0.8, duration: 120, useNativeDriver: true })
    ]).start(() => onPressedOut?.());
  };

  const containerStyle = {
    backgroundColor: backgroundShadow,
    borderRadius,
    shadowOffset: { width: 0, height: raiseLevel + 4 },
  };

  const frontStyle = {
    backgroundColor,
    transform: [{ translateY }],
    borderRadius,
  };

  return (
    <Pressable
      onPressIn={disabled ? null : handlePressIn}
      onPressOut={disabled ? null : handlePressOut}
      onPress={onPress}
      disabled={disabled}
    >
      <View style={[styles.container, containerStyle]}>
        <Animated.View style={[styles.front, frontStyle]}>
          {children}
        </Animated.View>
      </View>
    </Pressable>
  );
};

const styles = StyleSheet.create({
  container: { paddingBottom: 6 },
  front: { padding: 12, alignItems: 'center', justifyContent: 'center' }
});

export default AwesomeButton;

const AwesomeButton = ({ progress, onPress, activityColor = '#FFFFFF', backgroundProgress, ...props }) => {
  const progressValue = useRef(new Animated.Value(0)).current;
  const [isProcessing, setIsProcessing] = useState(false);

  const handlePress = () => {
    if (!progress || !onPress) return onPress?.();

    setIsProcessing(true);
    progressValue.setValue(0);

    onPress((next) => {
      Animated.timing(progressValue, {
        toValue: 1,
        duration: 1200,
        easing: Easing.ease,
        useNativeDriver: false,
      }).start(() => {
        setIsProcessing(false);
        next();
      });
    });
  };

  return (
    <AwesomeButtonCore {...props} onPress={handlePress}>
      {isProcessing && (
        <View style={styles.progressContainer}>
          <Animated.View 
            style={[styles.progressBar, { width: progressValue.interpolate({ inputRange: [0, 1], outputRange: ['0%', '100%'] }) }]}
          />
        </View>
      )}
      {props.children}
    </AwesomeButtonCore>
  );
};

export const ThemedButton = ({ name = 'blue', type = 'primary', children, ...props }) => {
