      backgroundColor={colors.backgroundColor}
      backgroundDarker={colors.backgroundDarker}
      backgroundShadow={colors.backgroundShadow}
      backgroundActive={colors.backgroundActive || '#C0C0C0'}
      borderColor={colors.borderColor}
      {...props}
    >
      {children}
    </AwesomeButton>
  );
};

