const AwesomeButton = ({ disabled, animatedPlaceholder = true, backgroundPlaceholder, activeOpacity = 1, ...props }) => {
  const opacity = disabled ? 0.6 : activeOpacity;
  const background = disabled ? (backgroundPlaceholder || '#C0C0C0') : props.backgroundColor;

  useEffect(() => {
    if (disabled) {
      // reset animation when disabled
      translateY.setValue(0);
    }
  }, [disabled]);

  return (
    <Animated.View style={{ opacity }}>
      <Pressable
        disabled={disabled}
        style={({ pressed }) => [{ opacity: pressed && !disabled ? 0.9 : 1 }]}
      >
        <CoreButton 
          backgroundColor={background}
          disabled={disabled}
          {...props}
        />
      </Pressable>
    </Animated.View>
  );
};
